var wg sync.WaitGroup
var resultsWg sync.WaitGroup // New WaitGroup for results consumption

// Start workers
for i := 0; i < numWorkers; i++ {
	wg.Add(1)
	go func(id int) {
		defer wg.Done()
		for job := range jobs {
			// Simulate some work
			time.Sleep(time.Millisecond)

			// BUG 1: Race Condition - FIX
			atomic.AddInt32(&processedCount, 1)

			results <- Result{JobID: job.ID, Val: job.ID * 2}
		}
	}(i)
}

// Send jobs
go func() {
	for i := 0; i < numJobs; i++ {
		jobs <- Job{ID: i}
	}
	close(jobs)
}()

// Close results channel AFTER all workers are done
go func() {
	wg.Wait()
	close(results)
}()

// Consume results concurrently
resultsWg.Add(1)
go func() {
	defer resultsWg.Done()
	for range results {
		// Just drain
	}
}()

resultsWg.Wait() // Wait for results to be consumed
